import{_ as e,o as a,c as s,a3 as r}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Comparisons","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Comparisons | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/guide/comparisons"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/guide/comparisons"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/guide/comparisons"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/guide/comparisons"}]]},"headers":[],"relativePath":"xclang/guide/comparisons.md","filePath":"en/xclang/guide/comparisons.md","lastUpdated":1791516064000}'),o={name:"xclang/guide/comparisons.md"};function n(i,t,d,l,c,h){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="comparisons" tabindex="-1">Comparisons <a class="header-anchor" href="#comparisons" aria-label="Permalink to &quot;Comparisons&quot;">​</a></h1><p>The toolchains people use for the jobs xclang does, what each does, and where xclang differs, in both directions. Facts are as of 2026-10-06, from the documentation of each project, linked. Corrections are welcome as <a href="https://github.com/clice-io/xclang/issues" target="_blank" rel="noreferrer">issues</a>.</p><h2 id="in-one-table" tabindex="-1">In One Table <a class="header-anchor" href="#in-one-table" aria-label="Permalink to &quot;In One Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>what it is</th><th>targets out of the box</th><th>sysroots and SDKs</th><th>C++ runtime in programs</th><th>Linux programs run on</th><th>build systems</th><th>compiler built with PGO</th></tr></thead><tbody><tr><td><strong>xclang</strong></td><td>clang, lld and six targets&#39; runtimes, prebuilt</td><td>Linux x64/arm64, Windows x64/arm64 (MinGW, MSVC), macOS x64/arm64</td><td>bundled; Apple&#39;s and Microsoft&#39;s SDKs fetched by the user from the vendor, or Xcode&#39;s</td><td>libc++, static; for MSVC targets, Microsoft&#39;s STL, static</td><td>glibc 2.17+</td><td>CMake package, Bazel module, conda</td><td>yes, PGO + ThinLTO, every host</td></tr><tr><td><strong>zig cc</strong> 0.17</td><td>Zig&#39;s driver around its clang</td><td>dozens: glibc, musl, MinGW, macOS, BSDs, WASI</td><td>libc sources and stubs bundled, built on first use</td><td>libc++, static</td><td>any glibc version chosen per target; 2.31 by default</td><td><code>zig build</code>; <code>CC=&quot;zig cc&quot;</code></td><td>not stated</td></tr><tr><td><strong>cargo-zigbuild</strong></td><td>zig cc as cargo&#39;s linker</td><td>Linux, macOS, as its README lists</td><td>through zig; macOS SDK from the user</td><td>through zig</td><td>glibc version chosen per target</td><td>cargo</td><td>as zig</td></tr><tr><td><strong>cross-rs</strong></td><td>cargo in Docker images with GCC cross toolchains</td><td>most of Rust&#39;s Linux, Windows and other targets</td><td>per-target images; Apple and MSVC images built by the user</td><td>libstdc++</td><td>2.31; 2.17 in <code>:centos</code> images</td><td>cargo</td><td>no; GCC</td></tr><tr><td><strong>llvm-mingw</strong></td><td>clang, lld, mingw-w64 and LLVM&#39;s runtimes</td><td>Windows i686, x86_64, armv7, arm64</td><td>bundled</td><td>libc++ DLL by default, static with <code>-static</code></td><td>no Linux targets</td><td>any, through <code>&lt;target&gt;-clang</code> names</td><td>yes, PGO + ThinLTO</td></tr><tr><td><strong>conda-forge compilers</strong></td><td>GCC, clang, MSVC activation packages</td><td>the conda platforms, in recipes</td><td><code>sysroot_linux-*</code> packages</td><td>shared, from <code>libstdcxx</code>/<code>libcxx</code> packages via <code>run_exports</code></td><td>glibc 2.17+, or 2.28 by opt-in</td><td>conda-build, rattler-build</td><td>not stated</td></tr><tr><td><strong>LLVM releases</strong></td><td>upstream binaries</td><td>the host only</td><td>none</td><td>host runtimes only</td><td>the host&#39;s glibc; the toolchain is built on Ubuntu 22.04</td><td>none</td><td>Linux, macOS: PGO + ThinLTO; Windows: PGO</td></tr><tr><td><strong>distro clang + GCC cross</strong></td><td>OS packages</td><td>one package set per target</td><td>distro packages per target</td><td>libstdc++, shared</td><td>the distribution&#39;s glibc</td><td>any</td><td>depends on the distribution</td></tr><tr><td><strong>Android NDK</strong></td><td>clang and bionic sysroots</td><td>Android ABIs × API levels</td><td>bundled</td><td>libc++, static or shared</td><td>Android</td><td>CMake, ndk-build</td><td>yes, with BOLT</td></tr><tr><td><strong>wasi-sdk</strong></td><td>clang and wasi-libc</td><td><code>wasm32-wasip1</code>, <code>wasip2</code></td><td>bundled</td><td>libc++, static</td><td>WASI</td><td>CMake toolchain file</td><td>not stated</td></tr><tr><td><strong>toolchains_llvm</strong> (Bazel)</td><td>rules around LLVM&#39;s release binaries</td><td>the host; cross with a user sysroot</td><td>the user&#39;s</td><td>libc++ static natively, the sysroot&#39;s libstdc++ when cross</td><td>the sysroot&#39;s</td><td>Bazel</td><td>as LLVM</td></tr><tr><td><strong>hermetic_cc_toolchain</strong> (Bazel)</td><td>rules around zig cc</td><td>Linux glibc and musl, windows-gnu, macOS &quot;not well tested&quot;</td><td>through zig</td><td>libc++, static</td><td>chosen per target</td><td>Bazel</td><td>as zig</td></tr></tbody></table><h2 id="zig-cc" tabindex="-1">zig cc <a class="header-anchor" href="#zig-cc" aria-label="Permalink to &quot;zig cc&quot;">​</a></h2><p><a href="https://andrewkelley.me/post/zig-cc-powerful-drop-in-replacement-gcc-clang.html" target="_blank" rel="noreferrer"><code>zig cc</code></a> is the closest in spirit: one download, <code>-target</code>, and nothing else. It is where a cross-compiling clang without a sysroot to install was shown to work. It differs from xclang in how it gets there:</p><ul><li><strong>It builds the runtimes on first use.</strong> Zig ships the sources of libc++, libc++abi, libunwind, compiler-rt and several C libraries. It builds what a target needs the first time, then caches it (<a href="https://ziglang.org/learn/overview/" target="_blank" rel="noreferrer">overview</a>). That is how it fits dozens of targets in a 55 MB download. xclang ships the runtimes of its six targets prebuilt: no first-build delay, and the same bytes for everyone. Fetching other targets as prebuilt archives is <a href="./../design/roadmap#target-archives">planned</a>.</li><li><strong>It has more targets today</strong>: musl, any glibc version per target (<code>x86_64-linux-gnu.2.17</code>), the BSDs and WASI. It also builds for macOS from any host, with Apple&#39;s libc headers and a <code>libSystem</code> stub (<a href="https://ziglang.org/download/0.17.0/release-notes.html" target="_blank" rel="noreferrer">0.17.0 release notes</a>). In xclang, the musl targets are in every archive from 23.1.2.10 on (<a href="./../design/roadmap#musl">unreleased</a>), and a newer glibc and the BSDs are <a href="./../design/roadmap#glibc-newer">considered</a>. xclang builds for macOS from any host too, with Apple&#39;s own SDK, which the user fetches (<a href="./../design/macos#the-sdk-on-linux-and-windows-hosts">macOS</a>).</li><li><strong>Its clang is Zig&#39;s.</strong> 0.17.0 has LLVM 22, with loop vectorization disabled to work around a regression since 0.16.0. xclang follows LLVM&#39;s releases with stock clang, built with PGO and ThinLTO.</li><li><strong>Runtimes.</strong> zig links libc++ statically, as xclang does, and has open issues with libc++ in more than one shared object (<a href="https://github.com/ziglang/zig/issues/24831" target="_blank" rel="noreferrer">#24831</a>). It ships no ASan runtime (<a href="https://github.com/ziglang/zig/issues/11403" target="_blank" rel="noreferrer">#11403</a>), and its <code>windows-msvc</code> target uses an installed Visual Studio. xclang has ASan, TSan, LSan, UBSan and libFuzzer for Linux and macOS, and its MSVC targets build from every host against an SDK the user fetches, with UBSan, and ASan and libFuzzer for x64.</li><li><strong>Integration.</strong> zig cc is a drop-in <code>CC</code>. xclang adds a CMake package with <code>import std</code>, a Bazel module, and libclang.</li></ul><p>Zig&#39;s issue tracker moved to Codeberg in November 2025; the GitHub issues above are as they were then.</p><h2 id="cargo-zigbuild-and-cross-rs" tabindex="-1">cargo-zigbuild and cross-rs <a class="header-anchor" href="#cargo-zigbuild-and-cross-rs" aria-label="Permalink to &quot;cargo-zigbuild and cross-rs&quot;">​</a></h2><p><a href="https://github.com/rust-cross/cargo-zigbuild" target="_blank" rel="noreferrer">cargo-zigbuild</a> makes zig cc the C compiler and linker of cargo. Its README lists Linux and macOS targets, and a glibc version per target.</p><p><a href="https://github.com/cross-rs/cross" target="_blank" rel="noreferrer">cross-rs</a> runs cargo inside Docker or Podman images that hold a GCC cross toolchain per target. <code>cross test</code> runs tests under QEMU. Its default images have glibc 2.31, or 2.17 in the <code>:centos</code> ones. It provides no images for Apple targets &quot;due to licensing reasons&quot;.</p><p>xclang works with cargo as zig does for cargo-zigbuild, with stock clang and xclang&#39;s runtimes. Today that is a documented recipe (<a href="./../integrations/cargo">Rust and Cargo</a>); a helper like cargo-zigbuild is <a href="./../design/roadmap#cargo-helper">considered</a>. Unlike cross-rs, xclang needs no container, and runs natively on Windows and macOS hosts. It also runs no tests under emulation.</p><h2 id="llvm-mingw" tabindex="-1">llvm-mingw <a class="header-anchor" href="#llvm-mingw" aria-label="Permalink to &quot;llvm-mingw&quot;">​</a></h2><p><a href="https://github.com/mstorsjo/llvm-mingw" target="_blank" rel="noreferrer">llvm-mingw</a> is clang, lld, mingw-w64 and the LLVM runtimes for Windows, from Linux, macOS and Windows hosts. xclang&#39;s MinGW targets are the same idea, and their sysroots use mingw-w64 too.</p><ul><li>llvm-mingw has more Windows architectures: i686, armv7, and arm64ec in its scripts. It has an msvcrt variant for older Windows, ASan on x86, and Control Flow Guard.</li><li>It links libc++ and libunwind as DLLs unless <code>-static</code> is given (<a href="https://github.com/mstorsjo/llvm-mingw/issues/333" target="_blank" rel="noreferrer">#333</a>). xclang links them in.</li><li>Its releases are built with PGO and ThinLTO too.</li><li>It has no Linux or macOS targets.</li></ul><h2 id="conda-forge-s-compilers" tabindex="-1">conda-forge&#39;s Compilers <a class="header-anchor" href="#conda-forge-s-compilers" aria-label="Permalink to &quot;conda-forge&#39;s Compilers&quot;">​</a></h2><p>The <code>cxx-compiler</code> of conda-forge is GCC on Linux, clang on macOS and MSVC on Windows, made to build conda packages. The C++ runtime is a shared library from a package, <code>libstdcxx</code> or <code>libcxx</code>, which <code>run_exports</code> adds to every package built with it. The Linux baseline is glibc 2.17, through the <code>sysroot_linux-*</code> packages (<a href="https://conda-forge.org/docs/maintainer/knowledge_base/" target="_blank" rel="noreferrer">knowledge base</a>).</p><p>That is right for an environment where conda provides the runtimes, and wrong for a program that leaves it. xclang is a conda package too, but not a compiler for conda-forge packages. It links its runtimes into every program, and has no <code>run_exports</code>.</p><h2 id="llvm-s-release-binaries" tabindex="-1">LLVM&#39;s Release Binaries <a class="header-anchor" href="#llvm-s-release-binaries" aria-label="Permalink to &quot;LLVM&#39;s Release Binaries&quot;">​</a></h2><p><a href="https://github.com/llvm/llvm-project/releases/tag/llvmorg-23.1.2" target="_blank" rel="noreferrer">LLVM&#39;s releases</a> are clang, lld and the runtimes for the host. They are built with PGO and ThinLTO on Linux and macOS (<code>clang/cmake/caches/Release.cmake</code>), and with PGO but no LTO on Windows. They carry no sysroot for another target, so a cross build needs one from elsewhere. An archive is 0.9 to 2 GB.</p><p>xclang 23.1.2.1 was built by them. xclang&#39;s archives are 86 to 94 MB, carry six targets, and run on glibc 2.17. On compile speed they are close on Linux and macOS (<a href="./../design/pgo#what-it-buys">PGO</a> has the numbers).</p><h2 id="distribution-clang-and-gcc-cross-toolchains" tabindex="-1">Distribution Clang and GCC Cross Toolchains <a class="header-anchor" href="#distribution-clang-and-gcc-cross-toolchains" aria-label="Permalink to &quot;Distribution Clang and GCC Cross Toolchains&quot;">​</a></h2><p>On Debian, <code>crossbuild-essential-arm64</code> brings <code>aarch64-linux-gnu-g++</code> and an arm64 glibc of the version of the distribution (<a href="https://packages.debian.org/trixie/crossbuild-essential-arm64" target="_blank" rel="noreferrer">packages.debian.org</a>). <code>g++-mingw-w64</code> is a MinGW GCC, and apt.llvm.org has every clang version. They are the default on a Linux machine, and well maintained. But:</p><ul><li>Their programs need the glibc of the distribution or newer, and <code>libstdc++.so.6</code>.</li><li>The programs of a MinGW GCC need <code>libstdc++-6.dll</code> and <code>libgcc_s_seh-1.dll</code>, unless linked with <code>-static</code>.</li><li>Each target is another set of packages.</li><li>They exist on Linux only.</li></ul><h2 id="android-ndk-and-wasi-sdk-the-precedents" tabindex="-1">Android NDK and wasi-sdk: The Precedents <a class="header-anchor" href="#android-ndk-and-wasi-sdk-the-precedents" aria-label="Permalink to &quot;Android NDK and wasi-sdk: The Precedents&quot;">​</a></h2><p>Both are one clang with bundled sysroots, the shape xclang has for desktop targets.</p><ul><li>The <a href="https://developer.android.com/ndk/guides/other_build_systems" target="_blank" rel="noreferrer">NDK</a> takes the target and API level in <code>--target=aarch64-linux-android21</code>, and its libc++ is static by default in CMake. Its <a href="https://developer.android.com/ndk/guides/cpp-support" target="_blank" rel="noreferrer">C++ library support</a> page states a rule that xclang&#39;s static runtimes also follow. &quot;You can only use a static variant of the C++ runtime if you have one and only one shared library in your application.&quot; Android&#39;s own clang is built with PGO, LTO and BOLT.</li><li><a href="https://github.com/WebAssembly/wasi-sdk" target="_blank" rel="noreferrer">wasi-sdk</a> is &quot;builds configured to set the default target and sysroot&quot;, which is what a config file per target does in xclang.</li></ul><h2 id="bazel-toolchains" tabindex="-1">Bazel Toolchains <a class="header-anchor" href="#bazel-toolchains" aria-label="Permalink to &quot;Bazel Toolchains&quot;">​</a></h2><p><a href="https://github.com/bazel-contrib/toolchains_llvm" target="_blank" rel="noreferrer">toolchains_llvm</a> downloads LLVM&#39;s release for the host. It cross-compiles with a sysroot the user brings, and then links the libstdc++ of that sysroot. <a href="https://github.com/uber/hermetic_cc_toolchain" target="_blank" rel="noreferrer">hermetic_cc_toolchain</a> is built on zig cc and has its targets. Its macOS support is &quot;not well tested&quot;, without a macOS SDK.</p><p>xclang&#39;s <a href="./../integrations/bazel">Bazel module</a> brings the sysroots itself, and registers a toolchain per host and target. Its actions hold no absolute paths, and it adds <code>import std</code>, sanitizer features and libclang.</p><h2 id="not-yet-supported" tabindex="-1">Not Yet Supported <a class="header-anchor" href="#not-yet-supported" aria-label="Permalink to &quot;Not Yet Supported&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>status</th><th>who has it</th></tr></thead><tbody><tr><td><a href="./../design/roadmap#musl">musl targets</a>, from 23.1.2.10 on</td><td><span class="status-badge warn">Unreleased</span></td><td>zig cc</td></tr><tr><td><a href="./../design/roadmap#android">Android</a>, <a href="./../design/roadmap#wasm">WebAssembly</a>, <a href="./../design/roadmap#freebsd">the BSDs</a>, <a href="./../design/roadmap#bare-metal">bare metal</a></td><td><span class="status-badge note">Considered</span></td><td>the NDK, wasi-sdk, zig cc</td></tr><tr><td><a href="./../design/roadmap#ios">iOS and Apple&#39;s other devices</a></td><td><span class="status-badge note">In research</span></td><td>Xcode</td></tr><tr><td><a href="./../design/roadmap#windows-7">Windows 7 and XP</a></td><td><span class="status-badge note">In research</span></td><td>llvm-mingw&#39;s msvcrt variant</td></tr><tr><td><a href="./../design/roadmap#libc-on-demand">Runtimes built from source with other options: MemorySanitizer, libc++ hardening, an ABI of one&#39;s own</a></td><td><span class="status-badge note">Planned</span></td><td>zig cc builds its runtimes on first use</td></tr></tbody></table><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><strong>No tests under emulation.</strong> Programs built for another target run on a machine of that target; xclang has nothing like <code>cross test</code>.</li><li><strong>No msvcrt.</strong> The MinGW targets use UCRT, which needs Windows 10 or later; an msvcrt variant is <a href="./../design/roadmap#msvcrt">not planned</a>.</li><li><strong>No shared C++ runtime across shared libraries.</strong> It is <a href="./../design/roadmap#shared-runtime">not planned</a>.</li></ul>',34)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
